self.addEventListener('install',event=>event.waitUntil((async()=>{
 const cache=await caches.open(CACHE),oldCaches=await Promise.all((await caches.keys()).filter(k=>k.startsWith('qian-shell-')&&k!==CACHE).reverse().map(k=>caches.open(k)));let cursor=0;const partial=new Map();await sendProgress();
 const report=async()=>{installProgress.bytes=[...partial.values()].reduce((a,b)=>a+b,0);await sendProgress();};
 try{await Promise.all(Array.from({length:Math.min(4,SHELL.length)},async()=>{while(cursor<SHELL.length&&installProgress.phase!=='failed'){const path=SHELL[cursor++],expected=ASSET_HASHES[path],request=new Request(path);let response=null;installProgress.current=path;installProgress.phase='loading';for(const old of oldCaches){const saved=await old.match(request);if(saved&&await contentHash(saved)===expected){response=saved;break;}}
  if(!response)response=await verifiedDownload(path,expected,size=>{partial.set(path,Math.min(size,ASSET_SIZES[path]||size));void report();});
  if(installProgress.phase==='failed')return;await cache.put(request,response);partial.set(path,ASSET_SIZES[path]||0);installProgress.done++;await report();
 }}));installProgress.phase='ready';await sendProgress();}catch(error){installProgress.phase='failed';installProgress.error=String(error.message);await sendProgress();throw error;}
})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{
 for(const name of await caches.keys()){const cache=await caches.open(name);for(const req of await cache.keys())if(new URL(req.url).pathname.endsWith('/assets/payment-qr-200.jpg'))await cache.delete(req);}

 // Keep one previous shell for on-demand recovery of already downloaded artwork.
 const old=(await caches.keys()).filter(k=>k.startsWith('qian-shell-')&&k!==CACHE).reverse();await Promise.all(old.slice(1).map(k=>caches.delete(k)));await self.clients.claim();
})()));
const mediaPending=new Map();
async function publicArtwork(request,path){
 const cache=await caches.open(MEDIA_CACHE),expected=ASSET_HASHES[path],key=new URL(path,self.location.href);key.searchParams.set('content',expected);const saved=await cache.match(key.href);if(saved)return saved;
 if(mediaPending.has(key.href))return (await mediaPending.get(key.href)).clone();
 const pending=(async()=>{for(const name of (await caches.keys()).filter(k=>k.startsWith('qian-shell-'))){const old=await (await caches.open(name)).match(new URL(path,self.location.href).href);if(old&&await contentHash(old)===expected){await cache.put(key.href,old.clone());return old;}}
 const response=await verifiedDownload(path,expected);await cache.put(key.href,response.clone());return response;})();mediaPending.set(key.href,pending);try{return(await pending).clone();}finally{mediaPending.delete(key.href);}
}
self.addEventListener('fetch',event=>{if(new URL(event.request.url).pathname.endsWith('/assets/payment-qr-200.jpg')){event.respondWith(Promise.resolve(new Response('Payment unavailable',{status:404})));return;}
 const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||url.pathname.includes('/api/'))return;
 const path='./'+url.pathname.slice(new URL('./',self.location.href).pathname.length);
 if(path.startsWith('./assets/')&&ASSET_HASHES[path]){event.respondWith(publicArtwork(event.request,path));return;}
 event.respondWith(caches.open(CACHE).then(async cache=>{if(event.request.mode==='navigate'&&[new URL('./',self.location.href).pathname,new URL('./index.html',self.location.href).pathname].includes(url.pathname)){const shell=await cache.match('./index.html');if(shell)return shell;}const cached=await cache.match(event.request);if(cached)return cached;try{return await fetch(event.request);}catch(error){if(event.request.mode==='navigate')return cache.match('./index.html');throw error;}}));
});
const pushKinds=['morning','noon','evening','gratitude','subscription'];
self.addEventListener('push',event=>{
  let kind='';try{const payload=event.data?.json();if(pushKinds.includes(payload?.kind))kind=payload.kind;}catch{}
  event.waitUntil(self.registration.showNotification('THE QIAN IMPERIUM',{body:'有一项日程待查看，请打开日课。',icon:new URL('icon-192-v2.png',self.registration.scope).href,tag:`daily-${kind||'reminder'}`,data:{kind}}));
});
self.addEventListener('notificationclick',event=>{
  event.notification.close();
  const kind=pushKinds.includes(event.notification.data?.kind)?event.notification.data.kind:'';
  const target=new URL(kind==='subscription'?'#subscription':kind?`#ritual/${kind}`:'./',self.registration.scope).href;
  event.waitUntil((async()=>{
    const windows=await self.clients.matchAll({type:'window',includeUncontrolled:true});
    for(const client of windows)if(client.url.startsWith(self.registration.scope)){await client.navigate(target);await client.focus();return;}
    await self.clients.openWindow(target);
  })());
});

self.addEventListener('message',event=>{
  if(event.data?.type==='GET_PROGRESS')event.source?.postMessage({...installProgress});
  if(event.data?.type==='GET_BUILD')event.ports[0]?.postMessage({build:CACHE});
  if(event.data?.type==='SKIP_WAITING')event.waitUntil(self.skipWaiting());
});
